mapper.insert:
BEGIN

	INSERT
	  INTO
		   PARTICIPANT_ROUTE_POINT (
								   	 POINT_ID
								   , ROUTE_ID
								   , POINT_ORDER
								   , LAT
								   , LNG
								   )
	VALUES
		   (
			 SEQ_PARTICIPANT_ROUTE_POINT.NEXTVAL
		   , (
			   SELECT
					  ROUTE_ID
				 FROM
					  PARTICIPANT_ROUTE
				WHERE
					  PARTICIPANT_ID = #{point.participantId}
			 )
		   , #{point.pointOrder}
		   , #{point.lat}
		   , #{point.lng}
		   );

END;
